-- SYNTHETIC benchmark data. Not real games: every row is generated by this script so the query
-- plans in docs/query_plans.md have realistic volume. Deterministic (setseed) and clearly marked
-- (games.pgn = 'SYNTHETIC', engine_version = 'synthetic').
SELECT setseed(0.42);

-- 2,000 games between 50 synthetic players. Players with a higher number are weaker.
INSERT INTO games (white, black, result, eco, opening, played_on, pgn, pgn_hash)
SELECT 'synth_' || lpad((1 + g % 50)::text, 2, '0'),
       'synth_' || lpad((1 + (g * 7) % 50)::text, 2, '0'),
       (ARRAY['1-0', '0-1', '1/2-1/2'])[1 + g % 3],
       (ARRAY['B20', 'C20', 'C50', 'D02', 'E60', 'A45', 'B90', 'C42'])[1 + g % 8],
       (ARRAY['Sicilian', 'Kings Pawn', 'Italian', 'Londons', 'Kings Indian',
              'Trompowsky', 'Najdorf', 'Petrovs'])[1 + g % 8],
       DATE '2024-01-01' + (g % 700),
       'SYNTHETIC',
       encode(sha256(('synthetic-' || g)::bytea), 'hex')
FROM generate_series(1, 2000) AS g;

-- 40 to 99 plies per game.
INSERT INTO moves (game_id, ply, move_number, color, san, uci, fen_before, phase)
SELECT g.id, p, (p + 1) / 2,
       CASE WHEN p % 2 = 1 THEN 'white' ELSE 'black' END,
       'e4', 'e2e4',
       'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
       CASE WHEN p <= 20 THEN 'opening' WHEN p <= 70 THEN 'middlegame' ELSE 'endgame' END
FROM games g
CROSS JOIN LATERAL generate_series(1, 40 + (g.id * 7) % 60) AS p
WHERE g.pgn = 'SYNTHETIC';

-- Expected points lost: mostly zero, occasionally large (random()^24 is heavy-tailed, giving
-- roughly 5-12% mistakes+blunders depending on the player); weaker players and the middlegame
-- produce more errors. Classification uses the same cutoffs as features.classify().
INSERT INTO evaluations
SELECT id, 'e7e5', cp_best, cp_best - (loss * 600)::int, loss,
       CASE WHEN loss <= 0.001 THEN 'best' WHEN loss <= 0.02 THEN 'excellent'
            WHEN loss <= 0.05 THEN 'good' WHEN loss <= 0.10 THEN 'inaccuracy'
            WHEN loss <= 0.20 THEN 'mistake' ELSE 'blunder' END,
       14, 'synthetic'
FROM (
    SELECT m.id,
           (random() * 600 - 300)::int AS cp_best,
           LEAST(1.0, power(random(), 24)
                      * (0.5 + 1.0 * (substr(CASE WHEN m.color = 'white' THEN g.white ELSE g.black END, 7)::int) / 50.0)
                      * CASE m.phase WHEN 'middlegame' THEN 1.4 WHEN 'opening' THEN 0.7 ELSE 1.0 END
           )::numeric(4, 3) AS loss
    FROM moves m JOIN games g ON g.id = m.game_id
    WHERE g.pgn = 'SYNTHETIC'
) s;

-- Facts for key moments: every mistake/blunder, plus ~2% of other moves.
INSERT INTO facts (move_id, facts, reasons)
SELECT e.move_id,
       jsonb_build_object(
           'classification', e.classification,
           'expected_points_lost', e.expected_points_lost,
           'played', jsonb_build_object(
               'ignored_threats', CASE WHEN random() < 0.25
                   THEN '[{"piece": "knight", "square": "f3"}]'::jsonb ELSE '[]'::jsonb END,
               'leaves_own_piece_hanging', CASE WHEN random() < 0.2
                   THEN '[{"piece": "bishop", "square": "c4"}]'::jsonb ELSE '[]'::jsonb END
           )),
       CASE WHEN e.classification IN ('mistake', 'blunder')
            THEN ARRAY[e.classification] ELSE ARRAY['brilliant'] END
FROM evaluations e
WHERE e.engine_version = 'synthetic'
  AND (e.classification IN ('mistake', 'blunder') OR random() < 0.02);

ANALYZE;
